export const PART_LABELS = {...COSMETIC_LABELS,...CHASSIS_LABELS,...DRIVE_LABELS,ecu:'ECU',turbo:'TURBO',exhaust:'EXHAUST',tyres:'TYRES',suspension:'SUSPENSION',brakes:'BRAKES',differential:'DIFFERENTIAL',clutch:'CLUTCH',intake:'INTAKE',radiator:'RADIATOR',oilCooler:'OIL COOLING',internals:'ENGINE INTERNALS',transmission:'GEARSET',finalDrive:'FINAL DRIVE',chassis:'CHASSIS',tyreWidth:'WHEEL WIDTH'};
export const DEFAULT_SELECTION = Object.freeze({...COSMETIC_DEFAULTS,...CHASSIS_DEFAULTS,...DRIVE_DEFAULTS,carId:'hachi',engineId:'i6t',ecu:'stock',turbo:'stock',exhaust:'street',tyres:'street',suspension:'street',brakes:'street',differential:'lsd',clutch:'street',intake:'stock',radiator:'stock',oilCooler:'stock',internals:'stock',transmission:'stock',finalDrive:'stock',chassis:'stock',tyreWidth:'stock'});
const copy = value => JSON.parse(JSON.stringify(value));
const find = (items,id,fallback) => items.find(item=>item.id===id) || items.find(item=>item.id===fallback) || items[0];

export function resolveBuild(request = {}) {
  const vehicle=find(VEHICLES,request.carId,DEFAULT_SELECTION.carId);
  const engine=find(ENGINES,request.engineId,vehicle.defaultEngine);
  const selection={...DEFAULT_SELECTION,carId:vehicle.id,engineId:engine.id};
  for(const key of Object.keys(PARTS))selection[key]=find(PARTS[key],request[key],DEFAULT_SELECTION[key]).id;
  if(!engine.turbo)selection.turbo='stock';
  sanitizeDriveSelection(selection);
  const ecu=selection.ecu==='track'?2:selection.ecu==='sport'?1:0;
  const turbo=selection.turbo==='race'?2:selection.turbo==='street'?1:0;
  const exhaust=selection.exhaust==='race'?2:selection.exhaust==='sport'?1:0;
  const suspension=selection.suspension==='race'?2:selection.suspension==='sport'?1:0;
  const brakes=selection.brakes==='race'?2:selection.brakes==='sport'?1:0;
  const clutch=selection.clutch==='race'?2:selection.clutch==='sport'?1:0;
  const level=key=>selection[key]==='race'?2:selection[key]==='sport'?1:0;
  const intake=level('intake'),radiator=level('radiator'),oilCooler=level('oilCooler'),internals=level('internals'),transmission=level('transmission'),tyreWidth=selection.tyreWidth==='race'?2:selection.tyreWidth==='wide'?1:0;
  const boostTarget=engine.turbo?engine.boostTarget+[0,12000,20000][ecu]+[0,20000,45000][turbo]:0;
  const redlineRpm=engine.redlineRpm+[0,300,500][ecu];
  const engineOptions=copy(engine.options);
  engineOptions.maxStepsPerUpdate=800;
  engineOptions.overrides={timingDrive:engine.rotors?'ideal':'chain',...engineOptions.overrides,idleRpm:engine.idleRpm,redlineRpm,revLimitRpm:engine.revLimitRpm+[0,300,500][ecu],boostTarget,
    exhaustDiameter:engine.exhaustDiameter*[1,1.12,1.23][exhaust],exhaustLength:engine.exhaustLength*[1,.92,.78][exhaust],exhaustDamping:engine.exhaustDamping*[1,.68,.38][exhaust]};
  if(engine.turbo&&turbo){
    // Per-machine hardware: more capacity, turbine area and inertia, not a force multiplier.
    const units=engine.options.family?.turboCount??1;
    Object.assign(engineOptions.overrides,{turboMaxFlow:[.30,.36,.45][turbo]/units,turboInertia:[.000034,.000049,.000072][turbo]/Math.pow(units,1.5),turbineArea:[.00055,.00064,.00078][turbo]/units,turboRadius:[.029,.031,.034][turbo]/Math.sqrt(units),compressorArea:[.0020,.00235,.00275][turbo]/units,turboMaxPressureRatio:[2.6,2.85,3.2][turbo]});
  }
  if(intake)Object.assign(engineOptions.overrides,{throttleCd:[.72,.77,.82][intake],intakeCd:[.70,.75,.79][intake],intakeLength:(engine.rotors?.30:.40)*[1,.86,.70][intake]});
  if(internals)engineOptions.overrides.inertia=(engineOptions.overrides.inertia??.27)*[1,.95,.88][internals];
  const chassis=resolveChassis(vehicle,selection),drivetrain=resolveDrivetrain(selection);
  const mass=drivetrain.driveMass+chassis.rackMass+chassis.barMass+vehicle.mass+engine.mass-vehicle.engineMass+[0,4,9][radiator]+[0,3,6][oilCooler]+(selection.chassis==='light'?-80:selection.chassis==='reinforced'?65:0)+[0,5,11][tyreWidth];
  const gears=transmission===2?vehicle.gears.map((ratio,i)=>ratio*[.90,.98,1.05,1.11,1.18,1.23][i]):transmission===1?vehicle.gears.map((ratio,i)=>ratio*[1,1.02,1.07,1.11,1.14,1.17][i]):[...vehicle.gears];
  const physics={...chassis,...drivetrain,mass,inertia:vehicle.inertia*(mass/vehicle.mass),wheelRadius:vehicle.wheelRadius,wheelInertia:vehicle.wheelInertia*[1,1.08,1.18][tyreWidth],halfTrack:vehicle.halfTrack+[0,.018,.038][tyreWidth],frontAxle:vehicle.frontAxle,rearAxle:vehicle.rearAxle,cgHeight:vehicle.cgHeight-[0,.018,.035][suspension],gears,finalDrive:vehicle.finalDrive*(selection.finalDrive==='short'?1.12:selection.finalDrive==='long'?.90:1),
    tyreWidth:[.27,.30,.34][tyreWidth],rollingResistanceFactor:[1,1.04,1.10][tyreWidth],radiatorEfficiency:[1,1.45,1.9][radiator],coolantCapacityExtra:[0,1,2][radiator],oilCoolingFactor:[1,2.1,3.3][oilCooler],oilCapacityExtra:[0,.7,1.2][oilCooler],oilSurgeProtection:[1,1.12,1.35][oilCooler],internalStrength:[1,1.35,1.8][internals],safeRpmFactor:[1,1.035,1.075][internals],drivetrainStrength:[1,1.3,1.65][transmission],bodyStrength:selection.chassis==='light'?.84:selection.chassis==='reinforced'?1.38:1,

    clutchCapacity:engine.clutchCapacity*[1,1.35,1.75][clutch],brakeTorque:vehicle.brakeTorque*[1,1.16,1.32][brakes],brakeBias:brakes?[.74,.77,.82][brakes]:vehicle.brakeBias,muMultiplier:(selection.tyres==='sport'?1.12:selection.tyres==='drift'?.88:1)*[1,1.045,1.085][tyreWidth],
    springRate:vehicle.springRate*[1,1.32,1.68][suspension],damperRate:vehicle.damperRate*[1,1.16,1.32][suspension],antiRollRate:vehicle.antiRollRate*[1,1.3,1.65][suspension],rideHeight:-[0,.025,.045][suspension],suspensionTravel:[.145,.125,.11][suspension],
    powerLock:selection.differential==='open'?0:selection.differential==='locked'?.96:.68,coastLock:selection.differential==='open'?0:selection.differential==='locked'?.72:.24,engineOptions,boostTarget,redlineRpm};
  const audio={...engine.audio,intake:Math.min(1,engine.audio.intake+[0,.05,.10][intake]),engineId:engine.id,exhaust:Math.min(1,engine.audio.exhaust+[0,.07,.12][exhaust]),brightness:engine.audio.brightness+[0,800,1600][exhaust],gearboxGain:engine.audio.gearboxGain*(clutch===2?1.15:1)};
  const stats={driveLayout:physics.driveLayout,frontDrivePercent:Math.round(physics.frontDriveShare*100),massKg:Math.round(mass),displacementCc:engine.displacementCc,redlineRpm,boostBar:boostTarget/100000,gearCount:vehicle.gears.length,clutchNm:Math.round(physics.clutchCapacity),brakeBias:Math.round(physics.brakeBias*100),wheelbaseM:vehicle.frontAxle+vehicle.rearAxle,finalDrive:physics.finalDrive,firstGear:gears[0],topGear:gears.at(-1),radiatorEfficiency:physics.radiatorEfficiency,oilCoolingFactor:physics.oilCoolingFactor,internalStrength:physics.internalStrength,bodyStrength:physics.bodyStrength,steeringLockDeg:physics.steeringLock*180/Math.PI,steeringRatio:physics.steeringRatio,frontRollRate:physics.antiRollRate*physics.frontRollFactor,rearRollRate:physics.antiRollRate*physics.rearRollFactor,tyreWidthMm:Math.round(physics.tyreWidth*1000)};
  return {selection,vehicle:copy(vehicle),engine:copy(engine),physics,audio,stats,signature:JSON.stringify(selection)};
}
